mapper.select:
select count(*) from proj_report_submit_log
where del_flag = '0'
  and submit_time >= #{begin}
  and submit_time < #{end}

select l.id, l.project_code, l.project_name, l.unit_name, l.submit_time, l.submit_by, l.batch_id, b.batch_no, l.create_time from proj_report_submit_log l left join proj_report_submit_batch b on b.id = l.batch_id where l.del_flag = '0' and l.project_code in
#{code}
order by l.submit_time desc

mapper.insert:
insert into proj_report_submit_log (
    project_code, project_name, unit_name, submit_time, submit_by, batch_id, create_time
) values (
    #{projectCode}, #{projectName}, #{unitName}, now(), #{submitBy}, #{batchId}, now()
)
on conflict (project_code) do nothing
